	if err := s.UpdatePlan(Plan{ID: "p", TaxRateBasisPoints: 20000}); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("bad update: %v", err)
	}
	if got := s.Status2("p"); got != good {
