273	// TestEventMembershipAcrossSegments 事件按发生时刻判断订阅期间归属：
274	// 开通时刻计入、终止时刻不计入、空档拒绝；跨取消与重新开通的重报规则。
275	func TestEventMembershipAcrossSegments(t *testing.T) {
276		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
277		mustPlan(t, s, planDef("a", 1000, 10, 5, 0))
278		mustAccount(t, s, "u")
279		mustSubscribe(t, s, "u", "a", utc(2026, 1, 1, 0, 0))
280	
281		// 开通时刻计入。
282		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 1}); err != nil {
283			t.Fatalf("event at activation: %v", err)
284		}
285	
286		mustCancel(t, s, "u") // end 2/1
287	
288		// 等待取消期间、终止前一刻仍接收。
289		clk.t = utc(2026, 1, 31, 23, 59)
290		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "last", At: utc(2026, 1, 31, 23, 59), Quantity: 1}); err != nil {
291			t.Fatalf("event just before end: %v", err)
292		}
293		// 终止时刻不计入。
294		clk.t = utc(2026, 2, 1, 0, 0)
295		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "at-end", At: utc(2026, 2, 1, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
296			t.Fatalf("event at end: %v", err)
297		}
298		// 空档期间拒绝。
299		clk.t = utc(2026, 2, 20, 0, 0)
300		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap", At: utc(2026, 2, 10, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
301			t.Fatalf("event in gap: %v", err)
302		}
303	
304		// 3/1 重新开通：2 月事件仍属空档，3/1 00:00（开通时刻）计入新段。
305		mustSubscribe(t, s, "u", "a", utc(2026, 3, 1, 0, 0))
306		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap2", At: utc(2026, 2, 15, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventBeforeSubscription) {
307			t.Fatalf("past gap after resubscribe: %v", err)
308		}
309		clk.t = utc(2026, 3, 2, 0, 0)
310		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "restart", At: utc(2026, 3, 1, 0, 0), Quantity: 1}); err != nil {
311			t.Fatalf("event at reactivation: %v", err)
312		}
313	
314		// 已接受事件原样重报，在取消和重新开通后仍成功、不重复累计。
315		old := Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 1}
316		if r, err := s.RecordEvent(old); err != nil || r.Accepted {
317			t.Fatalf("identical replay across segments: %+v %v", r, err)
318		}
319		// 标识相同而时刻或数量不同仍报冲突。
320		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 3, 1, 0, 0), Quantity: 1}); !errors.Is(err, ErrEventConflict) {
321			t.Fatalf("same id new time: %v", err)
322		}
323		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "start", At: utc(2026, 1, 1, 0, 0), Quantity: 2}); !errors.Is(err, ErrEventConflict) {
324			t.Fatalf("same id new qty: %v", err)
325		}
326		// 空档事件被拒不消耗标识：同标识之后落在订阅期间仍可上报。
327		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "gap", At: utc(2026, 3, 1, 12, 0), Quantity: 1}); err != nil {
328			t.Fatalf("rejected gap id reused in segment: %v", err)
329		}
330	}
