// TestStatusResultIsolation_NewOperationsDontRewriteOldSnapshot 反方向保障：保存一份
// 未改动的状态后，通过正常功能增加尚未出账月份的用量、为已有账单登记部分付款，
// 新查询应显示更新后的累计用量、已付金额和余额；旧结果保留取得时的数值与付清状态。
func TestStatusResultIsolation_NewOperationsDontRewriteOldSnapshot(t *testing.T) {
	s, clk := setupIndependentStatusAccount(t)
	wantEnd := utc(2026, 2, 1, 0, 0)

	// 1 月 15 日取得旧结果：用量 7、未付款、余额 1000、未付清，等待取消。
	old := mustStatus(t, s, "u")
	if !old.Subscribed || old.ScheduledEnd == nil || !old.ScheduledEnd.Equal(wantEnd) {
		t.Fatalf("old status: %+v", old)
	}
	oldJanUsage := usageOf(old, jan(2026)).Total
	oldSum := summaryOf(t, old, jan(2026))

	// 通过正常功能变化：2 月（尚未出账、且在原定终止 3/1 之前——本例终止为 2/1，
	// 故需要先撤回取消，再推进到 2 月增加用量，最后重新登记取消）。
	// 为保持场景直观，这里使用另一条路径：先记录 2 月用量必须发生在订阅期间内。
	// 本例订阅覆盖至 2/1（不含），2 月属于终止后的空档，因此先撤回取消以延续订阅，
	// 再增加 2 月用量、登记部分付款。
	if err := s.UndoCancelSubscription("u"); err != nil {
		t.Fatalf("undo cancel: %v", err)
	}
	clk.t = utc(2026, 2, 10, 0, 0)
	if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "feb-1", At: utc(2026, 2, 5, 0, 0), Quantity: 4}); err != nil {
		t.Fatalf("record feb usage: %v", err)
	}
	if _, err := s.RecordPayment("u", "pay-1", jan(2026), 400); err != nil {
		t.Fatalf("partial payment: %v", err)
	}

	// 新查询显示更新后的数据：新增 2 月用量 4；1 月账单已付 400、余额 600、未付清。
	fresh := mustStatus(t, s, "u")
	if got := usageOf(fresh, feb(2026)); got.Total != 4 {
		t.Fatalf("new status feb usage = %d, want 4", got.Total)
	}
	if got := usageOf(fresh, jan(2026)); got.Total != 7 {
		t.Fatalf("new status jan usage = %d, want 7", got.Total)
	}
	fsum := summaryOf(t, fresh, jan(2026))
	if fsum.Paid != 400 || fsum.Balance != 600 || fsum.Settled {
		t.Fatalf("new status bill summary: %+v", fsum)
	}
	if fresh.ScheduledEnd != nil {
		t.Fatalf("new status should have no scheduled end after undo: %+v", fresh)
	}

	// 旧结果仍保留取得时的数值与付清状态，且没有被加入 2 月用量。
	if got := usageOf(old, jan(2026)).Total; got != oldJanUsage || got != 7 {
		t.Fatalf("old snapshot jan usage changed to %d, want 7", got)
	}
	if len(old.MonthlyUsage) != 1 || old.MonthlyUsage[0].Period != jan(2026) {
		t.Fatalf("old snapshot gained later usage: %+v", old.MonthlyUsage)
	}
	osum := summaryOf(t, old, jan(2026))
	if osum.Paid != oldSum.Paid || osum.Balance != oldSum.Balance || osum.Settled != oldSum.Settled {
		t.Fatalf("old snapshot summary changed: %+v, want %+v", osum, oldSum)
	}
	if osum.Paid != 0 || osum.Balance != 1000 || osum.Settled {
		t.Fatalf("old snapshot should keep captured values: %+v", osum)
	}
	if old.ScheduledEnd == nil || !old.ScheduledEnd.Equal(wantEnd) {
		t.Fatalf("old snapshot lost captured end: %+v", old.ScheduledEnd)
	}

	// 再推进到 2 月出账期后，为 2 月出账并补齐付款，新查询继续反映当前；
	// 旧结果不受影响（旧结果取得时根本没有 2 月用量与账单）。
	clk.t = utc(2026, 3, 1, 0, 0)
	if _, err := s.CreateBill("u", feb(2026)); err != nil {
		t.Fatalf("create feb bill: %v", err)
	}
	fresh2 := mustStatus(t, s, "u")
	if len(fresh2.Bills) != 2 {
		t.Fatalf("new status bills = %+v", fresh2.Bills)
	}
	if len(old.MonthlyUsage) != 1 || len(old.Bills) != 1 {
		t.Fatalf("old snapshot mutated by later billing: usage=%+v bills=%+v", old.MonthlyUsage, old.Bills)
	}
}

