7	// 状态查询返回的各月用量、账单摘要与已安排的订阅终止时刻，是结果专属的副本：
8	// 调用方整理或修改拿到的内容只能留在该份结果中；同一账户后续通过公开功能发生的
9	// 变化既不能反过来改写此前保存的结果，也不被调用方对结果的改动影响。
10	// 本文件只回归已有查询行为，不新增任何公开功能。
11	
12	// mustStatus 是 Status 的测试便捷封装。
13	func mustStatus(t *testing.T, s *Service, acct string) AccountStatus {
14		t.Helper()
15		st, err := s.Status(acct)
16		if err != nil {
17			t.Fatalf("status %s: %v", acct, err)
18		}
19		return st
20	}
21	
22	// summaryOf 从状态中取指定账期的账单摘要；不存在时终止测试。
23	func summaryOf(t *testing.T, st AccountStatus, p Month) BillSummary {
24		t.Helper()
25		for _, b := range st.Bills {
26			if b.Period == p {
27				return b
28			}
29		}
30		t.Fatalf("bill summary %s not in status: %+v", p, st.Bills)
31		return BillSummary{}
32	}
33	
34	// usageOf 从状态中取指定账期的累计用量；不存在时终止测试。
35	func usageOf(st AccountStatus, p Month) Usage {
36		for _, u := range st.MonthlyUsage {
37			if u.Period == p {
38				return u
39			}
40		}
41		return Usage{Period: p}
42	}
43	
44	// assertStatusPeriods 校验状态中各月用量与账单均按账期先后排列。
45	func assertStatusPeriods(t *testing.T, st AccountStatus) {
46		t.Helper()
47		for i := 1; i < len(st.MonthlyUsage); i++ {
48			if !st.MonthlyUsage[i-1].Period.Before(st.MonthlyUsage[i].Period) {
49				t.Fatalf("monthly usage not in period order: %+v", st.MonthlyUsage)
50			}
51		}
52		for i := 1; i < len(st.Bills); i++ {
53			if !st.Bills[i-1].Period.Before(st.Bills[i].Period) {
54				t.Fatalf("bills not in period order: %+v", st.Bills)
55			}
56		}
57	}
58	
59	// setupIndependentStatusAccount 准备一个有多月用量与账单、并登记了按月取消的账户：
60	//   - 2026-01 用量 7、账单已出账（应付 1000，尚未付款）；
61	//   - 2026-01-15 登记按月取消，原定终止时刻为 2026-02-01 00:00 UTC，
62	//     此刻时钟停在 2026-01-15，订阅处于等待取消状态。
63	//
64	// 需要让订阅延续到 2 月的用例可先撤回取消再推进时钟。
65	func setupIndependentStatusAccount(t *testing.T) (*Service, *fakeClock) {
66		t.Helper()
67		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
68		mustPlan(t, s, planDef("p", 1000, 0, 0, 0))
69		mustAccount(t, s, "u")
70		mustSubscribe(t, s, "u", "p", utc(2026, 1, 1, 0, 0))
71		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "jan-1", At: utc(2026, 1, 10, 0, 0), Quantity: 7}); err != nil {
72			t.Fatalf("record jan usage: %v", err)
73		}
74		// 1 月已结束，出账后金额固定为月费 1000（税 0）。
75		clk.t = utc(2026, 2, 1, 0, 0)
76		if _, err := s.CreateBill("u", jan(2026)); err != nil {
77			t.Fatalf("create jan bill: %v", err)
78		}
79		// 回到 1 月内登记按月取消：原定终止时刻为 2/1。
80		clk.t = utc(2026, 1, 15, 12, 0)
81		mustCancel(t, s, "u")
82		return s, clk
83	}
84	
85	// TestStatusResultIsolation_MutatingSnapshot 调用方对返回结果的用量总数、账单摘要
86	// （已付金额、余额、付清状态）以及终止时刻的改动，只能留在该份结果中：
87	// 再次查询、按月查用量、查账单都必须仍显示真实数据。
88	func TestStatusResultIsolation_MutatingSnapshot(t *testing.T) {
89		s, _ := setupIndependentStatusAccount(t)
90		wantEnd := utc(2026, 2, 1, 0, 0)
91	
92		// 等待取消期间取得一份状态：有真实的 1 月用量 7、账单应付 1000、终止时刻。
93		st := mustStatus(t, s, "u")
94		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(wantEnd) {
95			t.Fatalf("initial status: %+v", st)
96		}
97		if got := usageOf(st, jan(2026)); got.Total != 7 {
98			t.Fatalf("initial jan usage = %d, want 7", got.Total)
99		}
100		sum := summaryOf(t, st, jan(2026))
101		if sum.TotalDue != 1000 || sum.Paid != 0 || sum.Balance != 1000 || sum.Settled {
102			t.Fatalf("initial jan summary: %+v", sum)
103		}
104		assertStatusPeriods(t, st)
105	
106		// 调用方在自己的这份结果上任意改动：用量总数、账单已付/余额/付清、终止时刻
107		// 改成更早或更晚。
108		st.MonthlyUsage[0].Total = 999
109		st.Bills[0].Paid = 1000
110		st.Bills[0].Balance = 0
111		st.Bills[0].Settled = true
112		earlier := utc(2026, 1, 20, 0, 0)
113		later := utc(2026, 3, 15, 0, 0)
114		*st.ScheduledEnd = earlier
115		*st.ScheduledEnd = later
116	
117		// 再次查询仍看到真实数据，且仍按账期先后展示。
118		st2 := mustStatus(t, s, "u")
119		if !st2.Subscribed || st2.ScheduledEnd == nil || !st2.ScheduledEnd.Equal(wantEnd) {
120			t.Fatalf("real end changed after mutating snapshot: %+v", st2)
121		}
122		if got := usageOf(st2, jan(2026)); got.Total != 7 {
123			t.Fatalf("real usage changed to %d, want 7", got.Total)
124		}
125		sum2 := summaryOf(t, st2, jan(2026))
126		if sum2.Paid != 0 || sum2.Balance != 1000 || sum2.Settled {
127			t.Fatalf("real bill summary changed: %+v", sum2)
128		}
129		assertStatusPeriods(t, st2)
130	
131		// 按月查询用量与查询账单也要保持原值，不能因为修改摘要而改变计量或收款结果。
132		if u, err := s.MonthlyUsage("u", jan(2026)); err != nil || u.Total != 7 {
133			t.Fatalf("monthly usage altered by snapshot edit: %+v %v", u, err)
134		}
135		b, err := s.GetBill("u", jan(2026))
136		if err != nil {
137			t.Fatalf("get bill: %v", err)
138		}
139		if b.Paid != 0 || b.Balance != 1000 || b.Settled {
140			t.Fatalf("bill altered by snapshot edit: %+v", b)
141		}
142	}
143	
144	// TestStatusResultIsolation_TwoSnapshotsIndependent 同一账户分别取得的两份状态彼此
145	// 独立：修改其中一份不能改变另一份；返回列表被重新排列或整段替换，也不能影响
146	// 下一次查询按账期先后展示的记录。
147	func TestStatusResultIsolation_TwoSnapshotsIndependent(t *testing.T) {
148		s, _ := setupIndependentStatusAccount(t)
149		wantEnd := utc(2026, 2, 1, 0, 0)
150	
151		a := mustStatus(t, s, "u")
152		b := mustStatus(t, s, "u")
153	
154		// 修改 a：用量、账单摘要、终止时刻全部改写；b 必须保持取得时的原值。
155		a.MonthlyUsage[0].Total = 111
156		a.Bills[0].Paid = 777
157		a.Bills[0].Balance = 223
158		a.Bills[0].Settled = true
159		*a.ScheduledEnd = utc(2026, 5, 1, 0, 0)
160	
161		if got := usageOf(b, jan(2026)); got.Total != 7 {
162			t.Fatalf("snapshot b usage changed by edit to a: %d", got.Total)
163		}
164		bsum := summaryOf(t, b, jan(2026))
165		if bsum.Paid != 0 || bsum.Balance != 1000 || bsum.Settled {
166			t.Fatalf("snapshot b bill changed by edit to a: %+v", bsum)
167		}
168		if b.ScheduledEnd == nil || !b.ScheduledEnd.Equal(wantEnd) {
169			t.Fatalf("snapshot b end changed by edit to a: %+v", b.ScheduledEnd)
170		}
171	
172		// 返回的列表被重新排列或整段替换：只影响这份结果本身，不影响下一次查询。
173		a.MonthlyUsage = append(a.MonthlyUsage, Usage{Period: apr(2026), Total: 5})
174		a.Bills = append(a.Bills, BillSummary{Period: mar(2026), TotalDue: 9})
175		// 逆序排列 a 自己的列表。
176		for i, j := 0, len(a.MonthlyUsage)-1; i < j; i, j = i+1, j-1 {
177			a.MonthlyUsage[i], a.MonthlyUsage[j] = a.MonthlyUsage[j], a.MonthlyUsage[i]
178		}
179		for i, j := 0, len(a.Bills)-1; i < j; i, j = i+1, j-1 {
180			a.Bills[i], a.Bills[j] = a.Bills[j], a.Bills[i]
181		}
182		a.ScheduledEnd = nil
183	
184		c := mustStatus(t, s, "u")
185		assertStatusPeriods(t, c)
186		if len(c.MonthlyUsage) != 1 || c.MonthlyUsage[0].Period != jan(2026) || c.MonthlyUsage[0].Total != 7 {
187			t.Fatalf("next status usage affected by snapshot list edits: %+v", c.MonthlyUsage)
188		}
189		if len(c.Bills) != 1 || c.Bills[0].Period != jan(2026) || c.Bills[0].Balance != 1000 {
190			t.Fatalf("next status bills affected by snapshot list edits: %+v", c.Bills)
191		}
192		if c.ScheduledEnd == nil || !c.ScheduledEnd.Equal(wantEnd) {
193			t.Fatalf("next status end affected by snapshot list edits: %+v", c.ScheduledEnd)
194		}
195	}
196	
197	// TestStatusResultIsolation_NewOperationsDontRewriteOldSnapshot 反方向保障：保存一份
198	// 未改动的状态后，通过正常功能增加尚未出账月份的用量、为已有账单登记部分付款，
199	// 新查询应显示更新后的累计用量、已付金额和余额；旧结果保留取得时的数值与付清状态。
200	func TestStatusResultIsolation_NewOperationsDontRewriteOldSnapshot(t *testing.T) {
201		s, clk := setupIndependentStatusAccount(t)
202		wantEnd := utc(2026, 2, 1, 0, 0)
203	
204		// 1 月 15 日取得旧结果：用量 7、未付款、余额 1000、未付清，等待取消。
205		old := mustStatus(t, s, "u")
206		if !old.Subscribed || old.ScheduledEnd == nil || !old.ScheduledEnd.Equal(wantEnd) {
207			t.Fatalf("old status: %+v", old)
208		}
209		oldJanUsage := usageOf(old, jan(2026)).Total
210		oldSum := summaryOf(t, old, jan(2026))
211	
212		// 通过正常功能变化：撤回取消让订阅延续到 2 月，在 1 月账单截止时刻（2/8）
213		// 之前增加尚未出账的 2 月用量，再为 1 月账单登记一笔部分付款。
214		if err := s.UndoCancelSubscription("u"); err != nil {
215			t.Fatalf("undo cancel: %v", err)
216		}
217		clk.t = utc(2026, 2, 2, 0, 0)
218		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "feb-1", At: utc(2026, 2, 2, 0, 0), Quantity: 4}); err != nil {
219			t.Fatalf("record feb usage: %v", err)
220		}
221		if _, err := s.RecordPayment("u", "pay-1", jan(2026), 400); err != nil {
222			t.Fatalf("partial payment: %v", err)
223		}
224	
225		// 新查询显示更新后的数据：新增 2 月用量 4；1 月账单已付 400、余额 600、未付清；
226		// 撤回后不再有终止时刻。
227		fresh := mustStatus(t, s, "u")
228		if got := usageOf(fresh, feb(2026)); got.Total != 4 {
229			t.Fatalf("new status feb usage = %d, want 4", got.Total)
230		}
231		if got := usageOf(fresh, jan(2026)); got.Total != 7 {
232			t.Fatalf("new status jan usage = %d, want 7", got.Total)
233		}
234		fsum := summaryOf(t, fresh, jan(2026))
235		if fsum.Paid != 400 || fsum.Balance != 600 || fsum.Settled {
236			t.Fatalf("new status bill summary: %+v", fsum)
237		}
238		if !fresh.Subscribed || fresh.ScheduledEnd != nil {
239			t.Fatalf("new status after undo should have no end: %+v", fresh)
240		}
241	
242		// 旧结果仍保留取得时的数值、付清状态与终止安排，且没有被加入 2 月用量。
243		if got := usageOf(old, jan(2026)).Total; got != oldJanUsage || got != 7 {
244			t.Fatalf("old snapshot jan usage changed to %d, want 7", got)
245		}
246		if len(old.MonthlyUsage) != 1 || old.MonthlyUsage[0].Period != jan(2026) {
247			t.Fatalf("old snapshot gained later usage: %+v", old.MonthlyUsage)
248		}
249		osum := summaryOf(t, old, jan(2026))
250		if osum.Paid != oldSum.Paid || osum.Balance != oldSum.Balance || osum.Settled != oldSum.Settled {
251			t.Fatalf("old snapshot summary changed: %+v, want %+v", osum, oldSum)
252		}
253		if osum.Paid != 0 || osum.Balance != 1000 || osum.Settled {
254			t.Fatalf("old snapshot should keep captured values: %+v", osum)
255		}
256		if old.ScheduledEnd == nil || !old.ScheduledEnd.Equal(wantEnd) {
257			t.Fatalf("old snapshot lost captured end: %+v", old.ScheduledEnd)
258		}
259	
260		// 后续再推进、出账也只影响新查询：旧结果的列表长度与数值保持取得时的样子。
261		clk.t = utc(2026, 3, 1, 0, 0)
262		if _, err := s.CreateBill("u", feb(2026)); err != nil {
263			t.Fatalf("create feb bill: %v", err)
264		}
265		if len(mustStatus(t, s, "u").Bills) != 2 {
266			t.Fatalf("new status should list two bills")
267		}
268		if len(old.MonthlyUsage) != 1 || len(old.Bills) != 1 {
269			t.Fatalf("old snapshot mutated by later billing: usage=%+v bills=%+v", old.MonthlyUsage, old.Bills)
270		}
271	}
272	
273	// TestStatusResultIsolation_UndoCancelKeptOnlyInOldSnapshot 撤回取消后，新查询不再
274	// 显示终止时刻，旧结果保留当时的安排；再修改这份旧结果不能重新登记取消，也不能
275	// 使已经撤回的订阅在原定时刻终止。
276	func TestStatusResultIsolation_UndoCancelKeptOnlyInOldSnapshot(t *testing.T) {
277		s, clk := setupIndependentStatusAccount(t)
278		wantEnd := utc(2026, 2, 1, 0, 0)
279	
280		old := mustStatus(t, s, "u")
281		if old.ScheduledEnd == nil || !old.ScheduledEnd.Equal(wantEnd) {
282			t.Fatalf("old status end: %+v", old)
283		}
284	
285		// 通过正常功能撤回取消。
286		if err := s.UndoCancelSubscription("u"); err != nil {
287			t.Fatalf("undo: %v", err)
288		}
289		fresh := mustStatus(t, s, "u")
290		if !fresh.Subscribed || fresh.ScheduledEnd != nil {
291			t.Fatalf("after undo new status should show no end: %+v", fresh)
292		}
293		// 旧结果仍保留当时的安排。
294		if old.ScheduledEnd == nil || !old.ScheduledEnd.Equal(wantEnd) {
295			t.Fatalf("old snapshot lost end after undo: %+v", old.ScheduledEnd)
296		}
297	
298		// 改写旧结果里的终止时刻（改早/改晚/置空）不能重新登记取消。
299		*old.ScheduledEnd = utc(2026, 1, 18, 0, 0)
300		if st := mustStatus(t, s, "u"); st.ScheduledEnd != nil {
301			t.Fatalf("editing old snapshot registered an earlier cancel: %+v", st)
302		}
303		*old.ScheduledEnd = utc(2026, 4, 1, 0, 0)
304		if st := mustStatus(t, s, "u"); st.ScheduledEnd != nil {
305			t.Fatalf("editing old snapshot registered a later cancel: %+v", st)
306		}
307		old.ScheduledEnd = nil
308		if st := mustStatus(t, s, "u"); st.ScheduledEnd != nil {
309			t.Fatalf("nil-ing old snapshot scheduled end: %+v", st)
310		}
311	
312		// 跨过原定终止时刻：订阅仍有效（取消确已撤回，而非由旧结果的时间决定）。
313		clk.t = utc(2026, 2, 1, 0, 0)
314		st := mustStatus(t, s, "u")
315		if !st.Subscribed || st.ScheduledEnd != nil || st.CurrentTerms.PlanID != "p" {
316			t.Fatalf("subscription ended at old snapshot's time despite undo: %+v", st)
317		}
318		// 在 1 月账单截止时刻（2/8）之前录一笔 2 月用量：订阅确实延续到了 2 月。
319		clk.t = utc(2026, 2, 2, 0, 0)
320		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "feb", At: utc(2026, 2, 2, 0, 0), Quantity: 1}); err != nil {
321			t.Fatalf("subscription should still accept february usage after undo: %v", err)
322		}
323		// 跨过年初原定终止时刻之后，订阅依旧有效（欠费只影响停用，不终止订阅）。
324		clk.t = utc(2026, 3, 1, 0, 0)
325		st = mustStatus(t, s, "u")
326		if !st.Subscribed {
327			t.Fatalf("subscription should remain active well after the undone end: %+v", st)
328		}
329	}
330	
331	// TestStatusResultIsolation_RealCancelEndsAtRegisteredTime 未撤回取消的账户仍须按
332	// 最初登记的终止时刻结束订阅，不能由调用方改过的时间决定。原定时刻之前仍有有效
333	// 订阅；到达该时刻后即使只查询状态，也应显示无有效订阅、无当前套餐且无终止安排。
334	// 此前保存的状态继续表示取得时尚在等待取消。
335	func TestStatusResultIsolation_RealCancelEndsAtRegisteredTime(t *testing.T) {
336		s, clk := setupIndependentStatusAccount(t)
337		wantEnd := utc(2026, 2, 1, 0, 0)
338	
339		// 取两份：一份原样保存，一份供调用方随意改时间。
340		saved := mustStatus(t, s, "u")
341		edited := mustStatus(t, s, "u")
342		// 调用方把自己那份的终止时刻分别改成更早与更晚。
343		*edited.ScheduledEnd = utc(2026, 1, 18, 0, 0)
344		*edited.ScheduledEnd = utc(2026, 4, 1, 0, 0)
345	
346		// 原定时刻之前仍有有效订阅，终止安排仍是最初登记的 2/1。
347		clk.t = utc(2026, 1, 31, 23, 59)
348		st := mustStatus(t, s, "u")
349		if !st.Subscribed || st.ScheduledEnd == nil || !st.ScheduledEnd.Equal(wantEnd) {
350			t.Fatalf("before real end: %+v", st)
351		}
352		if st.CurrentTerms.PlanID != "p" {
353			t.Fatalf("before real end current terms: %+v", st.CurrentTerms)
354		}
355	
356		// 到达原定时刻：即使只查询状态，也无有效订阅、无当前套餐、无终止安排。
357		clk.t = wantEnd
358		ended := mustStatus(t, s, "u")
359		if ended.Subscribed || ended.CurrentTerms != (PlanTerms{}) || ended.PendingChange != nil || ended.ScheduledEnd != nil {
360			t.Fatalf("at real end: %+v", ended)
361		}
362		// 历史用量与账单继续可查。
363		if len(ended.MonthlyUsage) != 1 || ended.MonthlyUsage[0].Total != 7 {
364			t.Fatalf("history usage at end: %+v", ended.MonthlyUsage)
365		}
366		if len(ended.Bills) != 1 || ended.Bills[0].Period != jan(2026) {
367			t.Fatalf("history bills at end: %+v", ended.Bills)
368		}
369	
370		// 此前保存、未改动的状态继续表示取得时尚在等待取消：原值不被后来的终止覆盖。
371		if !saved.Subscribed || saved.ScheduledEnd == nil || !saved.ScheduledEnd.Equal(wantEnd) {
372			t.Fatalf("saved snapshot changed at real end: %+v", saved)
373		}
374		if usageOf(saved, jan(2026)).Total != 7 {
375			t.Fatalf("saved snapshot usage changed at real end")
376		}
377		// 被调用方改过的那份保留调用方写入的 4/1，既不影响服务，也不被服务覆盖。
378		if edited.ScheduledEnd == nil || !edited.ScheduledEnd.Equal(utc(2026, 4, 1, 0, 0)) {
379			t.Fatalf("edited snapshot overwritten by service: %+v", edited.ScheduledEnd)
380		}
381	
382		// 原定时刻之后，被改成 4/1 的“更晚时间”不能让订阅延续：仍无有效订阅。
383		clk.t = utc(2026, 3, 15, 0, 0)
384		after := mustStatus(t, s, "u")
385		if after.Subscribed || after.CurrentTerms != (PlanTerms{}) || after.ScheduledEnd != nil {
386			t.Fatalf("subscription should not survive to edited later time: %+v", after)
387		}
388	}
389	
390	// TestStatusResultIsolation_NoArrangementCannotBeFabricated 没有取消安排时，查询中
391	// 的终止时刻为空；编辑返回结果（包括手动设置一个终止时刻）不能凭空产生安排。
392	func TestStatusResultIsolation_NoArrangementCannotBeFabricated(t *testing.T) {
393		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
394		mustPlan(t, s, planDef("p", 1000, 0, 0, 0))
395		mustAccount(t, s, "u")
396		mustSubscribe(t, s, "u", "p", utc(2026, 1, 1, 0, 0))
397		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "jan", At: utc(2026, 1, 10, 0, 0), Quantity: 3}); err != nil {
398			t.Fatalf("record usage: %v", err)
399		}
400	
401		st := mustStatus(t, s, "u")
402		if !st.Subscribed || st.ScheduledEnd != nil {
403			t.Fatalf("status without cancellation should have nil end: %+v", st)
404		}
405	
406		// 调用方在自己的结果里凭空放一个终止时刻。
407		fabricated := utc(2026, 2, 1, 0, 0)
408		st.ScheduledEnd = &fabricated
409		st.MonthlyUsage[0].Total = 42
410	
411		// 再次查询仍无安排，用量仍是真实值。
412		fresh := mustStatus(t, s, "u")
413		if fresh.ScheduledEnd != nil {
414			t.Fatalf("a cancellation was fabricated by editing status: %+v", fresh)
415		}
416		if usageOf(fresh, jan(2026)).Total != 3 {
417			t.Fatalf("usage changed by snapshot edit: %+v", fresh.MonthlyUsage)
418		}
419	
420		// 跨到 2 月：从未登记取消，订阅照常延续，不会在凭空的时刻终止。
421		clk.t = utc(2026, 2, 1, 0, 0)
422		atMonthBoundary := mustStatus(t, s, "u")
423		if !atMonthBoundary.Subscribed || atMonthBoundary.ScheduledEnd != nil {
424			t.Fatalf("subscription ended at fabricated time: %+v", atMonthBoundary)
425		}
426		if _, err := s.RecordEvent(Event{AccountID: "u", EventID: "feb", At: utc(2026, 2, 1, 0, 0), Quantity: 2}); err != nil {
427			t.Fatalf("usage at fabricated end should still be accepted: %v", err)
428		}
429	}
430

